var scenes=new System.Collections.Generic.List<object>();
for(int i=0;i<UnityEngine.SceneManagement.SceneManager.sceneCount;i++){var s=UnityEngine.SceneManagement.SceneManager.GetSceneAt(i);scenes.Add(new{s.name,s.path,s.isDirty,s.isLoaded});}
var npcs=UnityEngine.Object.FindObjectsByType<NPCController>(FindObjectsInactive.Include,FindObjectsSortMode.None).Select(n=>new{name=n.name,id=n.Data==null?null:n.Data.npcId,scene=n.gameObject.scene.path,position=n.transform.position.ToString("F3"),rotation=n.transform.eulerAngles.ToString("F3"),scale=n.transform.lossyScale.ToString("F3"),components=n.GetComponents<Component>().Select(c=>c.GetType().Name).ToArray(),children=n.GetComponentsInChildren<Transform>(true).Select(t=>new{name=t.name,scale=t.localScale.ToString("F3"),position=t.localPosition.ToString("F3"),rotation=t.localEulerAngles.ToString("F3")}).ToArray(),renderers=n.GetComponentsInChildren<Renderer>(true).Select(r=>new{name=r.name,type=r.GetType().Name,enabled=r.enabled,bounds=r.bounds.ToString(),materials=r.sharedMaterials.Select(m=>m==null?null:m.name+" : "+m.shader.name).ToArray()}).ToArray()}).ToArray();
return Newtonsoft.Json.JsonConvert.SerializeObject(new{playing=UnityEditor.EditorApplication.isPlaying,paused=UnityEditor.EditorApplication.isPaused,compiling=UnityEditor.EditorApplication.isCompiling,scenes,npcs,cameras=Camera.allCameras.Select(c=>new{c.name,position=c.transform.position.ToString("F3"),rotation=c.transform.eulerAngles.ToString("F3"),c.orthographicSize}).ToArray()});
